<?php
namespace Portal\Controllers;
use Portal\Models\{Categoria,Conteudo,Evento};
final class ConteudoController { public function __construct(private Conteudo $conteudos,private Categoria $categorias,private Evento $eventos) {} private function guard(bool $editor=false):void{if(empty($_SESSION['usuario'])){flash('erro','Entre para acessar o painel.');header('Location: '.url('login'));exit;}if($editor&&!in_array($_SESSION['usuario']['perfil'],['admin','editor'],true)){http_response_code(403);exit('Acesso restrito a administradores e editores.');}} public function dashboard():void{$this->guard();view('admin/dashboard',['conteudos'=>$this->conteudos->all(),'eventos'=>$this->eventos->all()]);} public function index():void{$this->guard();view('admin/conteudos',['conteudos'=>$this->conteudos->all()]);} public function create():void{$this->guard(true);view('admin/form_conteudo',['categorias'=>$this->categorias->active()]);} public function store():void{$this->guard(true);verify_csrf();$d=$_POST;if(trim($d['titulo']??'')===''||trim($d['resumo']??'')===''||trim($d['corpo']??'')===''||empty($d['categoria_id'])){flash('erro','Preencha todos os campos obrigatórios.');header('Location: '.url('admin/conteudos/novo'));exit;}$text=iconv('UTF-8','ASCII//TRANSLIT',$d['titulo']);$d['slug']=trim(preg_replace('/[^a-zA-Z0-9]+/','-',strtolower($text)),'-').'-'.date('YmdHis');try{$this->conteudos->save($d,(int)$_SESSION['usuario']['id']);flash('sucesso','Conteúdo salvo com sucesso.');}catch(\PDOException){flash('erro','Não foi possível salvar. Tente um título diferente.');}header('Location: '.url('admin/conteudos'));exit;} }
